#include <bits/stdc++.h>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n) || n <= 0) {
        cout << 0;
        return 0;
    }

    vector<int> arr(n);
    for (int& x : arr) cin >> x;

    if (n == 1) {
        cout << 0;
        return 0;
    }

    vector<pair<int, int>> vec;
    int prev = 0, cnt = 0;

    for (int i = n - 1; i > 0; --i) {
        int diff = arr[i] - arr[i - 1];
        if (diff == prev) {
            ++cnt;
        } else {
            cnt = 0;
            prev = diff;
        }
        vec.push_back({cnt, prev});
    }

    sort(vec.begin(), vec.end());
    pair<int, int> pr = vec.back();

    if (pr.first != 0 && arr[0] == 1 &&
        arr[1] - arr[0] == pr.second) {
        ++pr.first;
    }

    if (pr.first != 0 && arr[n - 1] == 1000 &&
        arr[n - 1] - arr[n - 2] == pr.second) {
        ++pr.first;
    }

    cout << pr.first;
    return 0;
}

